import type { FilterExpression } from '@wix/sdk-types'
import type {
  WixDataBulkUpdateOptions,
  WixDataItem,
  WixDataQuerySpec,
} from './types'

/**
 * Options builder for bulk update operations.
 *
 * Use this builder to configure bulk update behavior such as hooks suppression,
 * reference saving, and conditional updates.
 * @public
 * @builder
 * @documentationMaturity preview
 */
export interface WixDataBulkUpdateOptionsBuilder {
  /**
   * Sets whether to suppress update hooks.
   *
   * When `true`, the bulk update runs without triggering hooks.
   */
  withSuppressHooks(value: boolean): WixDataBulkUpdateOptionsBuilder
  /**
   * Sets whether to include draft items when updating items in bulk.
   * @internal
   */
  withShowDrafts(value: boolean): WixDataBulkUpdateOptionsBuilder
  /**
   * Sets whether to save referenced items when updating items in bulk.
   */
  withSaveReferences(value: boolean): WixDataBulkUpdateOptionsBuilder
  /**
   * Sets the condition that determines which items to update.
   */
  withCondition(
    value: FilterExpression<WixDataItem, WixDataQuerySpec>
  ): WixDataBulkUpdateOptionsBuilder
  /**
   * Builds the bulk update options object.
   */
  build(): WixDataBulkUpdateOptions
}

class WixDataBulkUpdateOptionsBuilderImpl
  implements WixDataBulkUpdateOptionsBuilder
{
  constructor(private readonly options: WixDataBulkUpdateOptions = {}) {}

  withSuppressHooks(value: boolean): WixDataBulkUpdateOptionsBuilder {
    return this.copy({ suppressHooks: value })
  }

  withShowDrafts(value: boolean): WixDataBulkUpdateOptionsBuilder {
    return this.copy({ showDrafts: value })
  }

  withSaveReferences(value: boolean): WixDataBulkUpdateOptionsBuilder {
    return this.copy({ saveReferences: value })
  }

  withCondition(
    value: FilterExpression<WixDataItem, WixDataQuerySpec>
  ): WixDataBulkUpdateOptionsBuilder {
    return this.copy({ condition: value.filter })
  }

  build(): WixDataBulkUpdateOptions {
    return {
      ...this.options,
    }
  }

  private copy(
    options: WixDataBulkUpdateOptions
  ): WixDataBulkUpdateOptionsBuilder {
    return new WixDataBulkUpdateOptionsBuilderImpl({
      ...this.options,
      ...options,
    })
  }
}

/**
 * Creates a new bulk update options builder.
 * @public
 * @documentationMaturity preview
 *
 * @example
 * ```ts title="Create a bulk update options builder"
 * import { items, BulkUpdateOptionsBuilder, Filter } from '@wix/data'
 *
 * const options = BulkUpdateOptionsBuilder()
 *   .withSuppressHooks(true)
 *   .withCondition(Filter('status').eq('active'))
 *   .build()
 *
 * const result = await items.bulkUpdate('myCollection', [
 *   { _id: 'foo', title: 'Updated' },
 *   { _id: 'bar', title: 'Updated' },
 * ], options)
 * ```
 */
export const BulkUpdateOptionsBuilder: () => WixDataBulkUpdateOptionsBuilder =
  () => new WixDataBulkUpdateOptionsBuilderImpl()
